import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor tallskinny_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ static void
gemm_device(int M, int N, int K,
            const T* __restrict__ A, int ldA,
            const T* __restrict__ B, int ldB,
            T* __restrict__ C, int ldC)
{
  // Global tensors: A (M,K) row-major, B (K,N) row-major, C (M,N) row-major
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(ldA, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(K, N), make_stride(ldB, Int<1>{}));
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(ldC, Int<1>{}));

  // CTA tiler: BLK_M x BLK_N x BLK_K
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<32>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{}); // (BLK_M, BLK_K, k)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X, _1, _1>{}); // (BLK_K, BLK_N, k)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)

  // Shared memory
  __shared__ T smemA[128 * 32];
  __shared__ T smemB[32 * 128];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<128>{}, Int<32>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<32>{}, Int<128>{}));

  // Thread layouts for global->shared copy (256 threads total)
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<8>{}, Int<32>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{});

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  int K_TILE_MAX = size<2>(tAgA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    copy(tAgA(_, _, k_tile), tAsA);
    copy(tBgB(_, _, k_tile), tBsB);

    __syncthreads();

    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  axpby(1.0f, tCrC, 0.0f, tCgC);
}

torch::Tensor tallskinny_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int64_t M = A.size(0);
  int64_t K = A.size(1);
  int64_t K2 = B.size(0);
  int64_t N = B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions of A and B must match");

  constexpr int BLK_M = 128;
  constexpr int BLK_N = 128;
  constexpr int BLK_K = 32;

  TORCH_CHECK(M % BLK_M == 0, "M must be a multiple of 128 for this kernel");
  TORCH_CHECK(N % BLK_N == 0, "N must be a multiple of 128 for this kernel");
  TORCH_CHECK(K % BLK_K == 0, "K must be a multiple of 32 for this kernel");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::empty({M, N}, A.options());

  dim3 block(256);
  dim3 grid((unsigned)(M / BLK_M), (unsigned)(N / BLK_N));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gemm_device<float><<<grid, block, 0, stream>>>(
      (int)M, (int)N, (int)K,
      A_c.data_ptr<float>(), (int)K,
      B_c.data_ptr<float>(), (int)N,
      C.data_ptr<float>(), (int)N
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gemm_device launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemm = load_inline(
    name="cute_tallskinny_gemm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["tallskinny_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Tall-skinny matmul C = A @ B implemented with a single custom CuTe GEMM kernel.
    """
    def __init__(self) -> None:
        super().__init__()
        self._ext = cute_gemm

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.tallskinny_matmul(A.contiguous(), B.contiguous())

